-- Preço de referência do SINAPI (Caixa/IBGE) para itens do catálogo sem oferta de loja.
-- Fonte: Relatório de Preços de Insumos, MT (Cuiabá), set/2026, sem desoneração. Só itens com insumo equivalente;
-- preco já está na unidade do catálogo (preço do insumo x fator). Não entra em cotação: é só referência na vitrine.

create table public.catalogo_referencias (
  item_id text primary key references public.catalogo_itens(id) on delete cascade,
  fonte text not null,
  codigo text not null,
  descricao text not null,
  unidade_origem text not null,
  fator numeric not null default 1 check (fator > 0),
  preco numeric not null check (preco > 0)
);

alter table public.catalogo_referencias enable row level security;

create policy "ver referencias" on public.catalogo_referencias for select to authenticated using (true);

on conflict (item_id) do update set fonte = excluded.fonte, codigo = excluded.codigo, descricao = excluded.descricao,
  unidade_origem = excluded.unidade_origem, fator = excluded.fator, preco = excluded.preco;
